// A standard implementation of Debounce
function debounce(func, delay) {
  let timeoutId;

  return function(...args) {
    // If called again, clear the previous timer
    clearTimeout(timeoutId);

    // Start a fresh timer
    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}

// Usage
const handleSearch = (query) => {
  console.log(`Fetching results for: ${query}`);
};

const debouncedSearch = debounce(handleSearch, 300);

// Simulating user typing rapidly
debouncedSearch('h');
debouncedSearch('he');
debouncedSearch('hel');
debouncedSearch('hello');

// Output: Only "Fetching results for: hello" is printed, 300ms later.


// A basic implementation of Throttle
function throttle(func, limit) {
  let inThrottle;

  return function(...args) {
    if (!inThrottle) {
      func.apply(this, args);
      inThrottle = true;
      setTimeout(() => {
        inThrottle = false;
      }, limit);
    }
  };
}
